INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (27, 16, 44, 0, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 100101, 155, "東山奈央", "人助け、応援", 2, "A", "人助けが大好き！　前向き格闘娘", "ヒヨリ", "トゥインクルウィッシュ", "獣人族", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, 17, 47, 0, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 100201, 158, "種田梨沙", "料理、人間観察", 2, "O", "戦闘のサポートが得意な、心優しい少女", "ユイ", "トゥインクルウィッシュ", "ヒューマン", 4);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (12, 18, 46, 0, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 100301, 163, "早見沙織", "読書、乗馬、お茶", 2, "B", "クールで何事にも真っ直ぐな剣士", "レイ", "トゥインクルウィッシュ", "魔族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 9, 27, 0, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 100401, 128, "諸星すみれ", "いたずら、探検", 5, "O", "探検好きのイタズラっ子", "ミソギ", "リトルリリカル", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (25, 12, 40, 0, "？？？", 100501, 146, "下田麻美", "ヒーローごっこ", 8, "O", "ヒーローに憧れる騎士見習いの少女", "マツリ", "王宮騎士団（NIGHTMARE）", "獣人族", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 13, 42, 0, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 100601, 150, "浅倉杏美", "サックス", 7, "O", "甘え上手なみんなの人気者", "アカリ", "悪魔偽王国軍（ディアボロス）", "魔族", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (23, 14, 32, 0, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 100701, 130, "雨宮天", "プリンを食べること", 7, "B", "プリン大好きゴースト娘", "ミヤコ", "悪魔偽王国軍（ディアボロス）", "魔族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 14, 40, 0, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 100801, 150, "大空直美", "鏡で自分を見ること", 15, "AB", "ボクは誰よりも美しい", "ユキ", "ヴァイスフリューゲル　ランドソル支部", "エルフ", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, 17, 45, 0, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 100901, 159, "髙野麻美", "小説執筆", 13, "A", "前世を信じる中二病患者、「疾風の冥姫」", "アンナ", "トワイライトキャラバン", "魔族", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 16, 42, 0, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 101001, 155, "内田真礼", "空想、ぬいぐるみ集め", 10, "O", "マホマホ王国のプリンセス", "マホ", "自警団（カォン）", "獣人族", 9);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (25, 15, 44, 0, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 101101, 156, "阿澄佳奈", "お裁縫", 3, "A", "人懐っこくてマシンガントークな妹系少女", "リノ", "ラビリンス", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 17, 46, 0, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 101201, 156, "大橋彩香", "妹と遊ぶこと、二度寝、昼寝、早寝", 6, "A", "みんなのために超能力を使う眠り姫", "ハツネ", "フォレスティエ", "エルフ", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (21, 18, 55, 0, "", 101301, 166, "佳村はるか", "読書、魔法", 13, "O", "オタク全開な魔法少女", "ナナカ", "トワイライトキャラバン", "魔族", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 15, 41, 0, "test", 101401, 152, "水瀬いのり", "読書、推理", 10, "AB", "頭脳明晰な美少女名探偵", "カスミ", "自警団（カォン）", "獣人族", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, 21, 54, 0, "test", 101501, 165, "國府田マリ子", "絵本作り", 6, "O", "母性溢れる優しいみんなの「ミサト先生」", "ミサト", "フォレスティエ", "エルフ", 9);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 17, 48, 0, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 101601, 167, "上坂すみれ", "ファッション", 14, "O", "天真爛漫で人気者のカリスマモデル", "スズナ", "ルーセント学院", "魔族", 4);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (7, 17, 53, 0, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 101701, 158, "高森奈津美", "踊り、空手", 10, "A", "いつでも「なんくるないさ～」な天然娘", "カオリ", "自警団（カォン）", "獣人族", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (14, 23, 52, 0, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 101801, 162, "伊藤静", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 14, "B", "多くの男性を魅了する無垢な女教師", "イオ", "ルーセント学院", "魔族", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 10, 21, 0, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 102001, 117, "日高里菜", "かわいいもの集め", 5, "O", "お歌もにんじんも、ウサギさんも大好き♪", "ミミ", "リトルリリカル", "獣人族", 4);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (9, 12, 40, 0, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 102101, 150, "植田佳奈", "観劇、おままごと", 9, "B", "泣き虫で臆病な守ってあげたい女の子", "クルミ", "サレンディア救護院", "ヒューマン", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 13, 40, 0, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 102201, 150, "原紗友里", "ゲーム全般", 7, "O", "人見知りであまのじゃくな女の子", "ヨリ", "悪魔偽王国軍（ディアボロス）", "魔族", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 14, 38, 0, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 102301, 148, "芹澤優", "屋内でできる遊び", 9, "B", "ぷうきちといつも一緒！", "アヤネ", "サレンディア救護院", "ヒューマン", 5);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (12, 15, 43, 0, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 102501, 154, "悠木碧", "ご奉仕", 9, "O", "お嬢さまのためにがんばるドジっ娘メイド", "スズメ", "サレンディア救護院", "ヒューマン", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (1, 17, 42, 0, "test", 102601, 144, "小岩井ことり", "あんパン", 11, "B", "遊びと睡眠が何より大事なぐうたら娘", "リン", "牧場（エリザベスパーク）", "獣人族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (30, 16, 43, 0, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 102701, 154, "橋本ちなみ", "実験、裁縫、料理", 13, "B", "運命の相手に一途すぎる乙女", "エリコ", "トワイライトキャラバン", "魔族", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (4, 17, 43, 0, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 102801, 156, "堀江由衣", "経営、お茶会", 9, "A", "救護院を経営する優しい庶民派お嬢様", "サレン", "サレンディア救護院", "エルフ", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 17, 40, 0, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 102901, 157, "日笠陽子", "舞台鑑賞、ダンス", 4, "B", "歌って踊れる大人気アイドル", "ノゾミ", "カルミナ", "ヒューマン", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (31, 16, 51, 0, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 103001, 163, "佐藤聡美", "忍法開発", 15, "O", "トーゴクの神秘、オシエテクダサイ！", "ニノン", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 18, 42, 0, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 103101, 157, "大坪由佳", "占い", 7, "AB", "占いが得意な霊能少女", "シノブ", "悪魔偽王国軍（ディアボロス）", "魔族", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (12, 18, 45, 0, "この私とともにいる限り、\nお金に不自由はさせませんわ！", 103201, 157, "松嵜麗", "慈善事業", 12, "AB", "一人前の商人を目指すパワフルお嬢様", "アキノ", "メルクリウス財団", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 20, 35, 0, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 103301, 142, "新田恵海", "漫才", 11, "B", "みんなを笑顔にするお笑い牧場主", "マヒル", "牧場（エリザベスパーク）", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (16, 22, 55, 0, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 103401, 164, "今井麻美", "ウインドーショッピング", 12, "A", "純情でほっとけない大人の女性", "ユカリ", "メルクリウス財団", "エルフ", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (2, 8, 21, 0, "test", 103601, 118, "小倉唯", "お勉強", 5, "A", "礼儀正しくしっかり者のちびっ子優等生", "キョウカ", "リトルリリカル", "エルフ", 2);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 13, 43, 0, "test", 103701, 149, "茅原実里", "剣術、年長者をからかう", 8, "A", "義理堅くてからかい好きな剣術少女", "トモ", "王宮騎士団（NIGHTMARE）", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 14, 40, 0, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 103801, 153, "小清水亜美", "読書、お散歩", 11, "A", "読書が趣味の病弱少女", "シオリ", "牧場（エリザベスパーク）", "獣人族", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (6, 13, 44, 0, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 104001, 158, "花澤香菜", "友達作りのイメトレ", 6, "AB", "「友達」に憧れる、エルフの森の女の子", "アオイ", "フォレスティエ", "エルフ", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 17, 46, 0, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 104201, 163, "福原綾香", "各種楽器", 4, "O", "人々を守るために歌う、唱喚士の少女", "チカ", "カルミナ", "ヒューマン", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (9, 17, 54, 0, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 104301, 168, "小松未可子", "お菓子作り", 10, "O", "男勝りで情に厚いワイルド娘", "マコト", "自警団（カォン）", "獣人族", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, "??", 50, 0, "test", 104401, 172, "丹下桜", "世界征服", 7, "A", "かつては夜を支配した最強の吸血鬼", "イリヤ", "悪魔偽王国軍（ディアボロス）", "魔族", 5);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (19, 18, 49, 0, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 104501, 157, "長妻樹里", "小説を読むこと", 15, "AB", "妄想大好き！　ほんとは照れ屋な女の子", "クウカ", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (1, 19, 48, 0, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 104601, 158, "沼倉愛美", "猫とたわむれること", 12, "AB", "弱きを助け強きをくじく猫娘", "タマキ", "メルクリウス財団", "獣人族", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (25, 25, 50, 0, "？？？", 104701, 171, "川澄綾子", "格闘技、湯浴み", 8, "A", "素顔を見せない冷静沈着な女性騎士", "ジュン", "王宮騎士団（NIGHTMARE）", "ヒューマン", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 20, 49, 0, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 104801, 163, "田所あずさ", "傭兵などのアルバイト", 12, "O", "仕事も私事も効率優先な傭兵少女", "ミフユ", "メルクリウス財団", "ヒューマン", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 18, 54, 0, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 104901, 168, "生天目仁美", "家事全般", 3, "O", "お姉ちゃんがお世話してあげるからねっ！", "シズル", "ラビリンス", "ヒューマン", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 11, 22, 0, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 105001, 120, "久野美咲", "ファッション誌鑑賞、コスメ集め", 14, "A", "ちょっとおませな恋に恋する女の子", "ミサキ", "ルーセント学院", "魔族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (7, 27, 53, 0, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 105101, 166, "三石琴乃", "研究、実験", 13, "A", "実験が趣味の危険な科学者", "ミツキ", "トワイライトキャラバン", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (14, 17, 100, 0, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 105201, 150, "徳井青空", "毛繕い、お喋り", 11, "A", "乙女チックなもふもふアニマル", "リマ", "牧場（エリザベスパーク）", "獣人族", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (28, 17, 33, 0, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 105301, 140, "辻あゆみ", "お菓子屋通い", 15, "A", "見た目も中身もお子ちゃまな異国の軍人", "モニカ", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (7, 14, 45, 0, "test", 105401, 153, "木戸衣吹", "裁縫", 4, "AB", "ファッション大好きなキュートガール", "ツムギ", "カルミナ", "ヒューマン", 9);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (7, 16, 43, 0, "test", 105501, 155, "大関英里", "観察", 15, "O", "どこまでも一途に慕う、純情乙女", "アユミ", "ヴァイスフリューゲル　ランドソル支部", "エルフ", 4);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 25, 54, 0, "test", 105601, 167, "佐藤利奈", "釣り", 13, "B", "人情味溢れる粋でいなせな「姉御」", "ルカ", "トワイライトキャラバン", "ヒューマン", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 17, 45, 0, "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", 105701, 156, "金元寿子", "冒険、おしゃべり", "", "O", "空への冒険を夢見る騎空士の少女", "ジータ", "？？？", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (31, 17, 46, 0, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 105801, 156, "M・A・O", "食べ歩き、料理", 1, "O", "いつも元気な腹ペコ少女", "ペコリーヌ", "美食殿", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 11, 35, 0, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 105901, 140, "伊藤美来", "瞑想、動植物の飼育", 1, "B", "主を慕う、小さなガイド役", "コッコロ", "美食殿", "エルフ", 5);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (2, 14, 39, 0, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 106001, 152, "立花理香", "猫と遊ぶ", 1, "A", "行き倒れの謎のネコミミ魔法使い", "キャル", "美食殿", "獣人族", 9);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 16, 40, 0, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 106101, 148, "潘めぐみ", "冒険、思い出話", "", "O", "さまよえる謎の少女", "ムイミ", "？？？", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (17, 15, 42, 0, "", 106301, 155, "優木かな", "キレイな葉っぱを集めること", "", "O", "森番を目指すエルフの少女", "アリサ", "？？？", "エルフ", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (14, 14, "???", 0, "", 106401, 147, "近藤玲奈", "読書、ストレッチ", 1, "B", "記憶喪失のドラゴン娘", "シェフィ", "美食殿", "ドラゴン族", 12);
