INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (17, 25, "???", 0, "", 106701, 168, "大西沙織", "絵画、読書", 17, "O", "妖しい微笑で全てを見透かす臥竜の頭領", "ホマレ", "ドラゴンズネスト", "ドラゴン族", 4);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (25, 25, "??", 0, "", 106801, 160, "沢城みゆき", "人間観察", 3, "AB", "秘密結社ラビリンスの『迷宮女王』", "ラビリスタ", "ラビリンス", "ヒューマン", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (1, 29, "??", 0, "", 106901, 166, "蒼井翔太", "占い、支配", "", "AB", "謎に包まれたランドソルの主", "カイザーインサイト", "？？？", "獣人族", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 24, "??", 0, "", 107001, 149, "井口裕香", "物真似、芸術鑑賞", "", "O", "研究所に隠れ住む物静かなお姉さん", "ネネカ", "？？？", "エルフ", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (7, 27, "??", 0, "", 107101, 165, "たかはし智秋", "強敵との闘争", 8, "O", "傍若無人な王宮騎士団副団長", "クリスティーナ", "王宮騎士団（NIGHTMARE）", "ヒューマン", 2);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (31, 17, 46, 0, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 107501, 156, "M・A・O", "食べ歩き、料理", 1, "O", "いつも元気な腹ペコ少女", "ペコリーヌ（サマー）", "美食殿", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 11, 35, 0, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 107601, 140, "伊藤美来", "瞑想、動植物の飼育", 1, "B", "主を慕う、小さなガイド役", "コッコロ（サマー）", "美食殿", "エルフ", 5);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (12, 15, 43, 0, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 107701, 154, "悠木碧", "ご奉仕", 9, "O", "お嬢さまのためにがんばるドジっ娘メイド", "スズメ（サマー）", "サレンディア救護院", "ヒューマン", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (2, 14, 39, 0, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 107801, 152, "立花理香", "猫と遊ぶ", 1, "A", "行き倒れの謎のネコミミ魔法使い", "キャル（サマー）", "美食殿", "獣人族", 9);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (1, 19, 48, 0, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 107901, 158, "沼倉愛美", "猫とたわむれること", 12, "AB", "弱きを助け強きをくじく猫娘", "タマキ（サマー）", "メルクリウス財団", "獣人族", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 20, 49, 0, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 108001, 163, "田所あずさ", "傭兵などのアルバイト", 12, "O", "仕事も私事も効率優先な傭兵少女", "ミフユ（サマー）", "メルクリウス財団", "ヒューマン", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 18, 42, 0, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 108101, 157, "大坪由佳", "占い", 7, "AB", "占いが得意な霊能少女", "シノブ（ハロウィン）", "悪魔偽王国軍（ディアボロス）", "魔族", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (23, 14, 32, 0, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 108201, 130, "雨宮天", "プリンを食べること", 7, "B", "プリン大好きゴースト娘", "ミヤコ（ハロウィン）", "悪魔偽王国軍（ディアボロス）", "魔族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 11, 22, 0, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 108301, 120, "久野美咲", "ファッション誌鑑賞、コスメ集め", 14, "A", "ちょっとおませな恋に恋する女の子", "ミサキ（ハロウィン）", "ルーセント学院", "魔族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 17, 46, 0, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 108401, 163, "福原綾香", "各種楽器", 4, "O", "人々を守るために歌う、唱喚士の少女", "チカ（クリスマス）", "カルミナ", "ヒューマン", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (9, 12, 40, 0, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 108501, 150, "植田佳奈", "観劇、おままごと", 9, "B", "泣き虫で臆病な守ってあげたい女の子", "クルミ（クリスマス）", "サレンディア救護院", "ヒューマン", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 14, 38, 0, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 108601, 148, "芹澤優", "屋内でできる遊び", 9, "B", "ぷうきちといつも一緒！", "アヤネ（クリスマス）", "サレンディア救護院", "ヒューマン", 5);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (27, 16, 44, 0, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 108701, 155, "東山奈央", "人助け、応援", 2, "A", "人助けが大好き！　前向き格闘娘", "ヒヨリ（ニューイヤー）", "トゥインクルウィッシュ", "獣人族", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, 17, 47, 0, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 108801, 158, "種田梨沙", "料理、人間観察", 2, "O", "戦闘のサポートが得意な、心優しい少女", "ユイ（ニューイヤー）", "トゥインクルウィッシュ", "ヒューマン", 4);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (12, 18, 46, 0, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 108901, 163, "早見沙織", "読書、乗馬、お茶", 2, "B", "クールで何事にも真っ直ぐな剣士", "レイ（ニューイヤー）", "トゥインクルウィッシュ", "魔族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (30, 16, 43, 0, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 109001, 154, "橋本ちなみ", "実験、裁縫、料理", 13, "B", "運命の相手に一途すぎる乙女", "エリコ（バレンタイン）", "トワイライトキャラバン", "魔族", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 18, 54, 0, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 109101, 168, "生天目仁美", "家事全般", 3, "O", "お姉ちゃんがお世話してあげるからねっ！", "シズル（バレンタイン）", "ラビリンス", "ヒューマン", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (1, 17, 55, 0, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 109201, 156, "日笠陽子", "読書", "", "AB", "英霊と契約を結んだマナリアの天才王女", "アン", "？？？", "ヒューマン", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (4, 16, 45, 0, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 109301, 144, "こやまきみこ", "食べること、眠ること", "", "O", "マナリア魔法学院の新入生", "ルゥ", "？？？", "ヒューマン", 2);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 17, 67, 0, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 109401, 167, "福原綾香", "ピアノ", "", "B", "人を超越した力を有す心優しい竜姫", "グレア", "？？？", "半人半竜", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (19, 18, 49, 0, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 109501, 157, "長妻樹里", "小説を読むこと", 15, "AB", "妄想大好き！　ほんとは照れ屋な女の子", "クウカ（オーエド）", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (31, 16, 51, 0, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 109601, 163, "佐藤聡美", "忍法開発", 15, "O", "トーゴクの神秘、オシエテクダサイ！", "ニノン（オーエド）", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (2, 17, "??", 0, "", 109701, 154, "水瀬いのり", "演劇鑑賞、詩文", "", "?", "鬼がかりの万能妹メイド", "レム", "？？？", "鬼族", 2);
