INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (25, 15, 44, 0, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 112901, 156, "阿澄佳奈", "お裁縫", 3, "A", "人懐っこくてマシンガントークな妹系少女", "リノ（ワンダー）", "ラビリンス", "ヒューマン", 8);
