INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, 17, 45, 0, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 113201, 159, "髙野麻美", "小説執筆", 13, "A", "前世を信じる中二病患者、「疾風の冥姫」", "アンナ（サマー）", "トワイライトキャラバン", "魔族", 7);
