INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 17, 46, 0, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 113401, 156, "大橋彩香", "妹と遊ぶこと、二度寝、昼寝、早寝", 6, "A", "みんなのために超能力を使う眠り姫", "ハツネ（サマー）", "フォレスティエ", "エルフ", 12);
