INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (25, 25, 50, 0, "", 113601, 171, "川澄綾子", "格闘技、湯浴み", 8, "A", "素顔を見せない冷静沈着な女性騎士", "ジュン（サマー）", "王宮騎士団（NIGHTMARE）", "ヒューマン", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 13, 42, 0, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 113701, 150, "浅倉杏美", "サックス", 7, "O", "甘え上手なみんなの人気者", "アカリ（エンジェル）", "悪魔偽王国軍（ディアボロス）", "魔族", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 13, 40, 0, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 113801, 150, "原紗友里", "ゲーム全般", 7, "O", "人見知りであまのじゃくな女の子", "ヨリ（エンジェル）", "悪魔偽王国軍（ディアボロス）", "魔族", 11);
