INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (12, 18, 46, 0, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 114001, 163, "早見沙織", "読書、乗馬、お茶", 2, "B", "クールで何事にも真っ直ぐな剣士", "レイ（ハロウィン）", "トゥインクルウィッシュ", "魔族", 1);
