INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (28, 17, 33, 0, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 114201, 140, "辻あゆみ", "お菓子屋通い", 15, "A", "見た目も中身もお子ちゃまな異国の軍人", "モニカ（マジカル）", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 7);
