INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (12, 18, 45, 0, "この私とともにいる限り、\nお金に不自由はさせませんわ！", 114401, 157, "松嵜麗", "慈善事業", 12, "AB", "一人前の商人を目指すパワフルお嬢様", "アキノ（クリスマス）", "メルクリウス財団", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (4, 17, 43, 0, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 114501, 156, "堀江由衣", "経営、お茶会", 9, "A", "救護院を経営する優しい庶民派お嬢様", "サレン（クリスマス）", "サレンディア救護院", "エルフ", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (16, 22, 55, 0, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 114601, 164, "今井麻美", "ウインドーショッピング", 12, "A", "純情でほっとけない大人の女性", "ユカリ（クリスマス）", "メルクリウス財団", "エルフ", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 16, 40, 0, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 114701, 148, "潘めぐみ", "冒険、思い出話", "", "O", "さまよえる謎の少女", "ムイミ（ニューイヤー）", "？？？", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 24, "??", 0, "", 115001, 149, "井口裕香", "物真似、芸術鑑賞", "", "O", "研究所に隠れ住む物静かなお姉さん", "ネネカ（ニューイヤー）", "？？？", "エルフ", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 11, 35, 0, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 115501, 140, "伊藤美来", "瞑想、動植物の飼育", 1, "B", "主を慕う、小さなガイド役", "コッコロ（儀装束）", "美食殿", "エルフ", 5);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, 17, 47, 0, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 115601, 158, "種田梨沙", "料理、人間観察", 2, "O", "戦闘のサポートが得意な、心優しい少女", "ユイ（儀装束）", "トゥインクルウィッシュ", "ヒューマン", 4);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 15, 41, 0, "", 115701, 152, "水瀬いのり", "読書、推理", 10, "AB", "頭脳明晰な美少女名探偵", "カスミ（サマー）", "自警団（カォン）", "獣人族", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (14, 17, 100, 0, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 115801, 150, "徳井青空", "毛繕い、お喋り", 11, "A", "乙女チックなもふもふアニマル", "リマ（シンデレラ）", "牧場（エリザベスパーク）", "獣人族", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (9, 17, 54, 0, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 115901, 168, "小松未可子", "お菓子作り", 10, "O", "男勝りで情に厚いワイルド娘", "マコト（シンデレラ）", "自警団（カォン）", "獣人族", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 16, 42, 0, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 116001, 155, "内田真礼", "空想、ぬいぐるみ集め", 10, "O", "マホマホ王国のプリンセス", "マホ（シンデレラ）", "自警団（カォン）", "獣人族", 9);
