INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (25, 16, "???", 0, "", 116601, 156, "小市眞琴", "格闘技", 17, "B", "拳で語る喧嘩屋ドラゴン少女", "カヤ（タイムトラベル）", "ドラゴンズネスト", "ドラゴン族", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (6, 13, 44, 0, "", 116701, 158, "花澤香菜", "友達作りのイメトレ", 6, "AB", "「友達」に憧れる、エルフの森の女の子", "アオイ（作業服）", "フォレスティエ", "エルフ", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (1, 19, 48, 0, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 116801, 158, "沼倉愛美", "猫とたわむれること", 12, "AB", "弱きを助け強きをくじく猫娘", "タマキ（作業服）", "メルクリウス財団", "獣人族", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (11, 20, 49, 0, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 116901, 163, "田所あずさ", "傭兵などのアルバイト", 12, "O", "仕事も私事も効率優先な傭兵少女", "ミフユ（作業服）", "メルクリウス財団", "ヒューマン", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (30, 16, 43, 0, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 117001, 154, "橋本ちなみ", "実験、裁縫、料理", 13, "B", "運命の相手に一途すぎる乙女", "エリコ（サマー）", "トワイライトキャラバン", "魔族", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 18, 54, 0, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 117101, 168, "生天目仁美", "家事全般", 3, "O", "お姉ちゃんがお世話してあげるからねっ！", "シズル（サマー）", "ラビリンス", "ヒューマン", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 17, 40, 0, "", 117201, 157, "日笠陽子", "舞台鑑賞、ダンス", 4, "B", "歌って踊れる大人気アイドル", "ノゾミ（サマー）", "カルミナ", "ヒューマン", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 17, 46, 0, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 117301, 163, "福原綾香", "各種楽器", 4, "O", "人々を守るために歌う、唱喚士の少女", "チカ（サマー）", "カルミナ", "ヒューマン", 6);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (7, 14, 45, 0, "", 117401, 153, "木戸衣吹", "裁縫", 4, "AB", "ファッション大好きなキュートガール", "ツムギ（サマー）", "カルミナ", "ヒューマン", 9);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (7, 27, 53, 0, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 117501, 166, "三石琴乃", "研究、実験", 13, "A", "実験が趣味の危険な科学者", "ミツキ（オーエド）", "トワイライトキャラバン", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 14, 40, 0, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 117601, 150, "大空直美", "鏡で自分を見ること", 15, "AB", "ボクは誰よりも美しい", "ユキ（オーエド）", "ヴァイスフリューゲル　ランドソル支部", "エルフ", 10);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (7, 17, 53, 0, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 117701, 158, "高森奈津美", "踊り、空手", 10, "A", "いつでも「なんくるないさ～」な天然娘", "カオリ（ハロウィン）", "自警団（カォン）", "獣人族", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (31, 16, 51, 0, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 117801, 163, "佐藤聡美", "忍法開発", 15, "O", "トーゴクの神秘、オシエテクダサイ！", "ニノン（ハロウィン）", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 17, 48, 0, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 117901, 167, "上坂すみれ", "ファッション", 14, "O", "天真爛漫で人気者のカリスマモデル", "スズナ（ハロウィン）", "ルーセント学院", "魔族", 4);
