INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (14, 23, 52, 0, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 119001, 162, "伊藤静", "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 14, "B", "多くの男性を魅了する無垢な女教師", "イオ（ノワール）", "ルーセント学院", "魔族", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (19, 18, 49, 0, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 119101, 157, "長妻樹里", "小説を読むこと", 15, "AB", "妄想大好き！　ほんとは照れ屋な女の子", "クウカ（ノワール）", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (3, 20, 35, 0, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 119201, 142, "新田恵海", "漫才", 11, "B", "みんなを笑顔にするお笑い牧場主", "マヒル（クリスマス）", "牧場（エリザベスパーク）", "ヒューマン", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (25, 15, 44, 0, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 119301, 156, "阿澄佳奈", "お裁縫", 3, "A", "人懐っこくてマシンガントークな妹系少女", "リノ（クリスマス）", "ラビリンス", "ヒューマン", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (23, 14, 32, 0, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 119901, 130, "雨宮天", "プリンを食べること", 7, "B", "プリン大好きゴースト娘", "ミヤコ（クリスマス）", "悪魔偽王国軍（ディアボロス）", "魔族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (24, 18, 54, 0, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 120001, 168, "生天目仁美", "家事全般", 3, "O", "お姉ちゃんがお世話してあげるからねっ！", "シズル（ノワール）", "ラビリンス", "ヒューマン", 10);
