INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, 17, 45, 0, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 121901, 159, "髙野麻美", "小説執筆", 13, "A", "前世を信じる中二病患者、「疾風の冥姫」", "アンナ（パイレーツ）", "トワイライトキャラバン", "魔族", 7);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 18, 42, 0, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 122001, 157, "大坪由佳", "占い", 7, "AB", "占いが得意な霊能少女", "シノブ（パイレーツ）", "悪魔偽王国軍（ディアボロス）", "魔族", 12);
