INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (16, 22, 55, 0, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 122201, 164, "今井麻美", "ウインドーショッピング", 12, "A", "純情でほっとけない大人の女性", "ユカリ（キャンプ）", "メルクリウス財団", "エルフ", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (6, "??", 41, 0, "", 122301, 149, "釘宮理恵", "お散歩、お料理", "", "AB", "けんぞくのご主人様", "ヴァンピィ", "？？？", "魔族", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (27, 16, 44, 0, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 122401, 155, "東山奈央", "人助け、応援", 2, "A", "人助けが大好き！　前向き格闘娘", "ヒヨリ（サマー）", "トゥインクルウィッシュ", "獣人族", 8);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (12, 18, 46, 0, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 122501, 163, "早見沙織", "読書、乗馬、お茶", 2, "B", "クールで何事にも真っ直ぐな剣士", "レイ（サマー）", "トゥインクルウィッシュ", "魔族", 1);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (5, 17, 47, 0, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 122601, 158, "種田梨沙", "料理、人間観察", 2, "O", "戦闘のサポートが得意な、心優しい少女", "ユイ（サマー）", "トゥインクルウィッシュ", "ヒューマン", 4);
