INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (16, 22, 55, 0, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 126801, 164, "今井麻美", "ウインドーショッピング", 12, "A", "純情でほっとけない大人の女性", "ユカリ（サマー）", "メルクリウス財団", "エルフ", 3);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (28, 20, 53, 0, "", 126901, 165, "原田彩楓", "歌、読書、詩を書くこと", 19, "O", "静寂を求め歌う陰気少女", "ランファ（サマー）", "レイジ・レギオン", "魔族", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (19, 18, 49, 0, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 127001, 157, "長妻樹里", "小説を読むこと", 15, "AB", "妄想大好き！　ほんとは照れ屋な女の子", "クウカ（サマー）", "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", 11);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (22, 18, 42, 0, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 127101, 157, "大坪由佳", "占い", 7, "AB", "占いが得意な霊能少女", "シノブ（サマー）", "悪魔偽王国軍（ディアボロス）", "魔族", 12);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (2, 14, 39, 0, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 127201, 152, "立花理香", "猫と遊ぶ", 1, "A", "行き倒れの謎のネコミミ魔法使い", "キャル（編入生）", "美食殿", "獣人族", 9);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (10, 17, 48, 0, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 127301, 167, "上坂すみれ", "ファッション", 14, "O", "天真爛漫で人気者のカリスマモデル", "スズナ（編入生）", "ルーセント学院", "魔族", 4);
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES (4, 17, 43, 0, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 127501, 156, "堀江由衣", "経営、お茶会", 9, "A", "救護院を経営する優しい庶民派お嬢様", "サレン（サラサリア）", "サレンディア救護院", "エルフ", 10);
